WITH payload AS (SELECT value AS j FROM jsonb_array_elements($DATA$[{"order":13,"title":"القواعد النحوية: إعراب فعل الأمر","content":"القواعد النحوية: إعراب فعل الأمر\n\nأهداف التعلّم\n• يميز فعل الأمر من الماضي والمضارع في ست جمل.\n• يحدد علامة بناء فعل أمر صحيح الآخر.\n• يوظف فعل الأمر في إرشاد مهذب.\n\nأتعلّم\nفعل الأمر يطلب حصول عمل بعد زمن التكلم. في «اكتبْ اسمك» كلمة «اكتبْ» فعل أمر مبني على السكون؛ لأنه صحيح الآخر ولم يتصل به شيء. وفي «اسعَ إلى الخير» فعل الأمر مبني على حذف حرف العلة. وقد يبنى فعل الأمر على حذف النون كما في «اكتبوا». نحول التعليمات المباشرة إلى صيغة مهذبة بقول «من فضلك، اكتبْ رقم القاعة».\n\nأمثلة توضيحية\nاقرأْ التعليمات، رتّبْ الأوراق، انتظرْ دورك. هذه أوامر صحيحة الآخر مبنية على السكون، وهي ليست أفعالًا مضارعة.\n\nأنشطة تدريبية\nحدّد فعل الأمر في «راجعْ الورقة قبل أن تسلمها». اضبط آخر «اجلس» عندما تخاطب شخصًا واحدًا. اكتب توجيهين مهذبين لزائر جديد.\n\nمفتاح الإجابة والتغذية الراجعة\nراجعْ؛ اجلسْ؛ مثل «افتحْ الباب بلطف» و«احفظْ الأوراق في الملف».\n\nتطبيق من الحياة\nعند إرشاد دارس إلى غرفة التسجيل، استخدم أمرًا واحدًا صحيحًا ومهذبًا لا يتضمن إساءة.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز فعل الأمر من الماضي والمضارع في ست جمل.","يحدد علامة بناء فعل أمر صحيح الآخر.","يوظف فعل الأمر في إرشاد مهذب."],"vocabulary":[{"word":"الأمر","meaning":"طلب أداء عمل"},{"word":"البناء","meaning":"ثبات نهاية الفعل وفق صورته"}],"quiz":{"prompt":"ما علامة بناء فعل الأمر «اكتبْ»؟","options":["السكون","الضمة","الفتحة الظاهرة دائمًا","الكسرة"],"correct":"السكون"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":14,"title":"الإنتاج الكتابي: الرسالة الشخصية (1)","content":"الإنتاج الكتابي: الرسالة الشخصية (1)\n\nأهداف التعلّم\n• يميز بين المرسل والمرسل إليه.\n• يكتب تحية مناسبة لرسالة شخصية.\n• يرتب المقدمة والمتن والخاتمة.\n\nأتعلّم\nالرسالة الشخصية وسيلة للتواصل مع قريب أو صديق. نبدأ باسم المخاطب وتحية واضحة، ثم نتناول سبب الكتابة في متن قصير، ونختم بدعاء أو عبارة تقدير واسم المرسل. مثال من ضاديوم: «صديقي علي، السلام عليكم. أكتب لأطمئن على صحتك بعد غيابك عن الدرس. نرجو أن نراك قريبًا. صديقك سالم». ينبغي ألا نضع بيانات شخصية خاصة لا حاجة لها.\n\nأمثلة توضيحية\nرسالة شخصية: «أختي العزيزة، أشكرك على مساعدتك في تعلم استخدام الهاتف. أخوك أحمد». يظهر اسم المخاطب، والغرض، والتوقيع.\n\nأنشطة تدريبية\nحدد المرسل والمرسل إليه في المثال الأول. رتب: توقيع / تحية / الغرض. اكتب رسالة من أربع جمل تطمئن فيها على صديق.\n\nمفتاح الإجابة والتغذية الراجعة\nالمرسل سالم، والمرسل إليه علي؛ الترتيب تحية ثم الغرض ثم التوقيع. تقبل رسالة مهذبة لها سبب واضح.\n\nتطبيق من الحياة\nاكتب رسالة شكر لأحد أفراد الأسرة مستخدمًا عبارات تحترم خصوصيته وتذكر المساعدة دون تفاصيل محرجة.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز بين المرسل والمرسل إليه.","يكتب تحية مناسبة لرسالة شخصية.","يرتب المقدمة والمتن والخاتمة."],"vocabulary":[{"word":"المرسل","meaning":"كاتب الرسالة"},{"word":"المتن","meaning":"الفقرات التي تحمل الغرض"}],"quiz":{"prompt":"ما الجزء الذي يوضح سبب إرسال الرسالة؟","options":["المتن","التوقيع وحده","عنوان الملف","رقم الصفحة"],"correct":"المتن"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":15,"title":"القواعد النحوية: الفاعل","content":"القواعد النحوية: الفاعل\n\nأهداف التعلّم\n• يحدد الفاعل في جملة فعلية مثبتة.\n• يميز علامة رفع الفاعل المفرد.\n• يبدل اسم الفاعل دون تغيير الحدث.\n\nأتعلّم\nالفاعل اسم مرفوع يدل على من قام بالفعل، أو اتصف به بحسب معنى الجملة. في «فتحَ الموظفُ النافذةَ» الفاعل «الموظفُ» مرفوع بالضمة، و«النافذةَ» مفعول به. وقد يأتي الفاعل بعد الفعل أو يتصل به ضميرًا مثل «كتبتُ». لا نحكم على الكلمة من موضعها وحده؛ نسأل: من قام بالفعل؟ ونتحقق من إعرابها.\n\nأمثلة توضيحية\nوصلَ البريدُ صباحًا؛ الفاعل البريدُ. ساعدَتْ فاطمةُ جارتَها؛ الفاعل فاطمةُ.\n\nأنشطة تدريبية\nحدّد الفاعل في «قرأَ سالمٌ التنبيهَ». استبدل «سالمٌ» بـ«الموظفُ». ضع الحركة الصحيحة على كلمة «الطبيب» في «حضرَ الطبيبُ».\n\nمفتاح الإجابة والتغذية الراجعة\nالفاعل «سالمٌ»؛ «قرأ الموظفُ التنبيهَ»؛ «الطبيبُ» مرفوع بالضمة.\n\nتطبيق من الحياة\nاكتب جملة تصف من استلم وثيقة في العمل وحدد الاسم الذي أدى الفعل.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحدد الفاعل في جملة فعلية مثبتة.","يميز علامة رفع الفاعل المفرد.","يبدل اسم الفاعل دون تغيير الحدث."],"vocabulary":[{"word":"الفاعل","meaning":"اسم يدل على من قام بالفعل"},{"word":"الرفع","meaning":"حالة إعرابية من علاماتها الضمة"}],"quiz":{"prompt":"من الفاعل في «أرسلَ الأبُ رسالةً»؟","options":["الأبُ","رسالةً","أرسلَ","لا يوجد"],"correct":"الأبُ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":16,"title":"الإملاء: الهمزة المتوسطة المفتوحة وما قبلها حرف ساكن غير المد","content":"الإملاء: الهمزة المتوسطة المفتوحة وما قبلها حرف ساكن غير المد\n\nأهداف التعلّم\n• يشرح أثر سكون الحرف السابق للهمزة المفتوحة.\n• يكتب «مسألة» و«فجأة» كتابة سليمة.\n• يميز هذه الحالة من همزة قبلها حرف مد.\n\nأتعلّم\nعند رسم الهمزة المتوسطة ننظر إلى حركتها وحركة الحرف السابق. إذا كانت الهمزة مفتوحة وقبلها حرف صحيح ساكن، مثل «مَسْأَلَة» و«فَجْأَة»، كتبت على ألف؛ لأن الفتحة أقوى من السكون، ومناسب الفتحة الألف. أما إذا سبق الهمزة حرف مد فقد تختلف القاعدة وتحتاج فحصًا خاصًا؛ لذلك لا نعمم هذا المثال على كل كلمة فيها سكون.\n\nأمثلة توضيحية\n«مسألة» فيها السين ساكنة والهمزة مفتوحة. «فجأة» فيها الجيم ساكنة والهمزة مفتوحة. نقرأ الكلمة ثم نكتبها مع تحديد كرسي الهمزة.\n\nأنشطة تدريبية\nأكمل رسم «مسـ_لة» و«فجـ_ة». ما حركة الحرف قبل الهمزة في الكلمتين؟ اكتب جملة قصيرة تحوي كلمة «مسألة».\n\nمفتاح الإجابة والتغذية الراجعة\nمسألة، فجأة؛ الحرف السابق ساكن؛ مثال «حللتُ مسألةً في الوقت المحدد».\n\nتطبيق من الحياة\nعند إرسال سؤال مكتوب إلى المعلم، راجع رسم كلمة «مسألة» قبل الإرسال.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يشرح أثر سكون الحرف السابق للهمزة المفتوحة.","يكتب «مسألة» و«فجأة» كتابة سليمة.","يميز هذه الحالة من همزة قبلها حرف مد."],"vocabulary":[{"word":"حرف صحيح ساكن","meaning":"حرف ليس مدًا وخالٍ من الحركة"},{"word":"كرسي الهمزة","meaning":"شكل الحرف الذي تحمل عليه"}],"quiz":{"prompt":"لماذا كتبت الهمزة على ألف في «فَجْأَة»؟","options":["لأنها مفتوحة وما قبلها ساكن صحيح","لأنها مكسورة","لأنها في أول الكلمة","لأن ما قبلها ألف مد"],"correct":"لأنها مفتوحة وما قبلها ساكن صحيح"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":17,"title":"الإنتاج الكتابي: الرسالة الشخصية (2)","content":"الإنتاج الكتابي: الرسالة الشخصية (2)\n\nأهداف التعلّم\n• يراجع لغة الرسالة وخلوها من العبارات الجارحة.\n• ينظم أحداثًا شخصية بتسلسل مفهوم.\n• يعيد تحرير رسالة بعد ملاحظة زميل.\n\nأتعلّم\nفي المرحلة الثانية نطور الرسالة الشخصية من مسودة قصيرة إلى رسالة مترابطة. نراجع: هل حددت سبب الكتابة؟ هل العبارات مناسبة للمخاطب؟ هل تتصل جملة بأخرى؟ في رسالة دعوة لصديق، من الأفضل كتابة المكان والموعد بوضوح، ثم طلب رد مختصر. عند الكتابة بالهاتف ننتبه إلى عدم إرسال العنوان الكامل في مجموعة عامة؛ فقد تكفي وسيلة تواصل خاصة.\n\nأمثلة توضيحية\nمسودة غير واضحة: «تعال في وقت ما». بعد المراجعة: «يسعدني حضورك مساء الخميس؛ سأرسل لك تفاصيل الموعد في رسالة خاصة».\n\nأنشطة تدريبية\nحسّن «لماذا تأخرت؟ أنت مهمل» إلى سؤال مهذب. أضف خاتمة لرسالة زيارة مريض. راجع الرسالة التي كتبتها سابقًا من جهة الترتيب والتهجئة.\n\nمفتاح الإجابة والتغذية الراجعة\nمثال «اطمئن عليك وأرجو أن تكون بخير، هل تحتاج أي مساعدة؟»؛ خاتمة «مع أطيب الدعوات بالشفاء، صديقك...»\n\nتطبيق من الحياة\nقبل إرسال رسالة إلى قريب، راجع اسم المخاطب والسبب والتاريخ وتأكد من خصوصية البيانات.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يراجع لغة الرسالة وخلوها من العبارات الجارحة.","ينظم أحداثًا شخصية بتسلسل مفهوم.","يعيد تحرير رسالة بعد ملاحظة زميل."],"vocabulary":[{"word":"مراجعة","meaning":"فحص النص لتحسينه"},{"word":"ترابط","meaning":"اتصال الأفكار في تسلسل مفهوم"}],"quiz":{"prompt":"ما التحسين الأهم عند مراجعة رسالة شخصية؟","options":["وضوح الغرض وملاءمة اللغة","حذف التحية دائمًا","إضافة تفاصيل غير مؤكدة","كتابة فقرة بلا علامات"],"correct":"وضوح الغرض وملاءمة اللغة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":18,"title":"القراءة: البحرين تتكلم - دراسة القصيدة كاملة وحفظ القصيدة كاملة","content":"القراءة: البحرين تتكلم - دراسة القصيدة كاملة وحفظ القصيدة كاملة\n\nأهداف التعلّم\n• يميز موضوع الانتماء في نص تدريبي أصلي.\n• يشرح صورة تعبيرية بسيطة عن الوطن.\n• يتدرب على الإلقاء مع الفصل بين النص الأصلي والقصيدة الرسمية.\n\nأتعلّم\nالعنوان المسجل في الخطة هو «البحرين تتكلم» وتتضمن المهمة الرسمية دراسة القصيدة كاملة وحفظها، لكن نص القصيدة وفهرس الكتاب لم تتم مطابقتهما هنا. لذلك نقدم تدريبًا أصليًا مختلفًا، وليس بديلًا عن حفظ القصيدة: «صوت البحر في صباح المدينة يذكرنا بالعمل والصبر. يلتقي الناس في المدارس والأسواق، ولكل إنسان دور في خدمة المكان الذي يحبه». نميز المعنى المباشر من التعبير المجازي، ثم نقرأ بأسلوب واضح.\n\nأمثلة توضيحية\nالتعبير «صوت البحر يذكرنا بالصبر» فيه تصوير للبحر وكأنه يبعث رسالة، ولا يعني أن البحر يتحدث حقيقة. الفكرة هي ارتباط الإنسان بوطنه وعمله.\n\nأنشطة تدريبية\nما المكانان المذكوران في النص الأصلي؟ فسّر عبارة «صوت البحر يذكرنا بالصبر». اكتب ثلاث جمل عن سلوك يحافظ على مكان عام. احفظ فقط النص الرسمي بعد التحقق من مصدره.\n\nمفتاح الإجابة والتغذية الراجعة\nالمدارس والأسواق؛ العبارة صورة تربط البحر بالصبر والعمل؛ تقبل جمل عملية مثل المحافظة على النظافة واحترام المرافق. الحفظ الرسمي غير مُتحقق منه في هذه المسودة.\n\nتطبيق من الحياة\nسجّل بصوتك فقرة أصلية قصيرة عن خدمة المجتمع، مع مراعاة الوقف الواضح وعدم الادعاء أنها القصيدة المقررة.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز موضوع الانتماء في نص تدريبي أصلي.","يشرح صورة تعبيرية بسيطة عن الوطن.","يتدرب على الإلقاء مع الفصل بين النص الأصلي والقصيدة الرسمية."],"vocabulary":[{"word":"انتماء","meaning":"صلة الإنسان بمكانه ومجتمعه"},{"word":"صورة تعبيرية","meaning":"أسلوب يرسم معنى في الخيال"}],"quiz":{"prompt":"ما وضع النص التدريبي هنا مقارنة بقصيدة «البحرين تتكلم»؟","options":["نص أصلي داعم لا يحل محل القصيدة الرسمية","النص الرسمي الكامل","دليل حفظ القصيدة المقررة","صورة من الكتاب"],"correct":"نص أصلي داعم لا يحل محل القصيدة الرسمية"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":19,"title":"القواعد النحوية: المفعول به","content":"القواعد النحوية: المفعول به\n\nأهداف التعلّم\n• يحدد المفعول به في ثلاث جمل فعلية.\n• يميز الفاعل عن المفعول به.\n• يضبط المفعول به المفرد بالفتحة في مثال واضح.\n\nأتعلّم\nالمفعول به اسم منصوب وقع عليه فعل الفاعل في الجملة المتعدية. «قرأَ الدارسُ الإعلانَ»: الدارس فاعل مرفوع؛ الإعلان مفعول به منصوب بالفتحة. نسأل ماذا قرأ الدارس؟ فنحصل على المفعول به. ليست كل الأفعال بحاجة إلى مفعول؛ فـ«جلسَ الدارسُ» جملة تامة. وقد تكون علامة النصب مختلفة في المثنى والجمع، لكن البداية بالمفرد.\n\nأمثلة توضيحية\nأعدَّ الموظفُ التقريرَ. شرحَ المدربُ التعليماتِ؛ «التقريرَ» منصوب بالفتحة و«التعليماتِ» جمع مؤنث سالم منصوب بالكسرة.\n\nأنشطة تدريبية\nحدد المفعول في «نظّمَ سالمٌ الملفاتِ». استبدل الملفات بكلمة «الموعد» واضبطها. لماذا لا يوجد مفعول به في «خرج الموظفُ»؟\n\nمفتاح الإجابة والتغذية الراجعة\nالملفاتِ؛ «نظم سالمٌ الموعدَ»؛ لأن فعل «خرج» لازم هنا واكتفى بالفاعل.\n\nتطبيق من الحياة\nصف إجراء في مكتب باستخدام جملة فيها فاعل ومفعول به، مثل تسجيل موعد أو قراءة رسالة.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحدد المفعول به في ثلاث جمل فعلية.","يميز الفاعل عن المفعول به.","يضبط المفعول به المفرد بالفتحة في مثال واضح."],"vocabulary":[{"word":"المفعول به","meaning":"اسم وقع عليه فعل الفاعل"},{"word":"الفعل المتعدي","meaning":"فعل يتجاوز فاعله إلى مفعول"}],"quiz":{"prompt":"ما المفعول به في «قرأَ سالمٌ الرسالةَ»؟","options":["الرسالةَ","سالمٌ","قرأَ","لا يوجد"],"correct":"الرسالةَ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":20,"title":"القواعد النحوية: المبتدأ والخبر","content":"القواعد النحوية: المبتدأ والخبر\n\nأهداف التعلّم\n• يميّز ركني الجملة الاسمية.\n• يرفع مبتدأ وخبرًا مفردين بالضمة.\n• يحول وصفًا قصيرًا إلى جملة اسمية تامة.\n\nأتعلّم\nالجملة الاسمية تبدأ غالبًا بمبتدأ نتحدث عنه، ثم خبر يكمل الفائدة. «الدرسُ مفيدٌ»: الدرسُ مبتدأ مرفوع بالضمة، ومفيدٌ خبر مرفوع بالضمة. إذا قلنا «الدرسُ» فقط لم تتم الفائدة. قد يأتي الخبر شبه جملة، مثل «الكتابُ على الطاولة»؛ فلا نعامله كخبر مفرد مرفوع بالضمة. نحاول أولًا التمييز بين المثالين.\n\nأمثلة توضيحية\n«المكتبةُ مفتوحةٌ» مبتدأ وخبر مفرد. «الطلابُ في القاعةِ» مبتدأ وخبر شبه جملة.\n\nأنشطة تدريبية\nعيّن الخبر في «الشارعُ نظيفٌ». أكمل «الورقةُ ...» بخبر مناسب. ضع الحركتين في «القلم جديد».\n\nمفتاح الإجابة والتغذية الراجعة\nالخبر «نظيفٌ»؛ مثل «الورقةُ واضحةٌ»؛ «القلمُ جديدٌ».\n\nتطبيق من الحياة\nاكتب جملتين اسميتين تصف بهما مكان التعلم أو خدمات مكتبة الحي.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميّز ركني الجملة الاسمية.","يرفع مبتدأ وخبرًا مفردين بالضمة.","يحول وصفًا قصيرًا إلى جملة اسمية تامة."],"vocabulary":[{"word":"مبتدأ","meaning":"اسم تبدأ به الجملة الاسمية غالبًا"},{"word":"خبر","meaning":"جزء يتم به معنى المبتدأ"}],"quiz":{"prompt":"ما الخبر في «الموعدُ قريبٌ»؟","options":["قريبٌ","الموعدُ","الموعد","لا يوجد خبر"],"correct":"قريبٌ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":21,"title":"القواعد النحوية: الأفعال الناسخة","content":"القواعد النحوية: الأفعال الناسخة\n\nأهداف التعلّم\n• يوضح أثر «كان» في جملة اسمية بسيطة.\n• يميز اسم كان وخبرها.\n• يكون جملة صحيحة باستخدام «أصبح».\n\nأتعلّم\nتدخل «كان وأخواتها» على الجملة الاسمية، فترفع المبتدأ اسمًا لها وتنصب الخبر خبرًا لها. نقول «الجوُّ معتدلٌ» ثم «كان الجوُّ معتدلًا». بقي «الجوُّ» مرفوعًا وصار «معتدلًا» منصوبًا. «أصبح الطريقُ مزدحمًا» مثال آخر، ويشير «أصبح» إلى حدوث الحالة صباحًا أو الصيرورة بحسب السياق. لا نضع الفتحة على الاسم، بل على الخبر المفرد.\n\nأمثلة توضيحية\n«الدرسُ سهلٌ» تصبح «صار الدرسُ سهلًا». «المركزُ مفتوحٌ» تصبح «أصبح المركزُ مفتوحًا».\n\nأنشطة تدريبية\nحوّل «الطقسُ جميلٌ» إلى جملة تبدأ بـ«كان». حدّد اسم كان وخبرها. صحح «كان الجوَّ لطيفٌ».\n\nمفتاح الإجابة والتغذية الراجعة\n«كان الطقسُ جميلًا»؛ اسمها الطقسُ وخبرها جميلًا؛ «كان الجوُّ لطيفًا».\n\nتطبيق من الحياة\nدوّن تغيرًا حدث في يومك بعبارة تبدأ بـ«أصبح»، ثم راجع ضبط الخبر.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يوضح أثر «كان» في جملة اسمية بسيطة.","يميز اسم كان وخبرها.","يكون جملة صحيحة باستخدام «أصبح»."],"vocabulary":[{"word":"ناسخ","meaning":"فعل يغير حكم المبتدأ والخبر"},{"word":"خبر كان","meaning":"جزء منصوب يكمل معنى كان"}],"quiz":{"prompt":"ما الضبط الصحيح بعد «كان»؟","options":["كان المكانُ نظيفًا","كان المكانَ نظيفٌ","كان المكانَ نظيفًا","كان المكانُ نظيفٌ"],"correct":"كان المكانُ نظيفًا"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":22,"title":"الإملاء: الهمزة المتوسطة المضمومة","content":"الإملاء: الهمزة المتوسطة المضمومة\n\nأهداف التعلّم\n• يحدد حركة الهمزة في كلمات مختارة.\n• يفسر رسم الهمزة المضمومة على واو في أمثلة مناسبة.\n• يكتب كلمتي «مَسْؤُول» و«رُؤُوس» دون تغيير معانيهما.\n\nأتعلّم\nإذا كانت الهمزة المتوسطة مضمومة، ننظر إلى حركتها وحركة ما قبلها؛ الضمة تناسب الواو ما لم توجد كسرة أقوى. مثال «مَسْؤُول»: الهمزة مضمومة وما قبلها ساكن صحيح، فتكتب على واو. ومثال «رُؤُوس» تظهر الهمزة على واو، مع الانتباه إلى الرسم المعجمي. أما «فِئَة» فكسرة ما قبل الهمزة أقوى، فترسم على ياء رغم فتحها. القاعدة لا تعتمد على ضمة الهمزة وحدها بمعزل عن الحرف السابق.\n\nأمثلة توضيحية\n«المسؤولُ يقرأُ الرسالةَ». «يتفاءلُ الناسُ بالمستقبل» فيها همزة متوسطة على ألف؛ لأننا لا نساوي بين كل الهمزات.\n\nأنشطة تدريبية\nأكمل «مسـ_ول» و«ر_وس». اذكر حركة الهمزة في «مسؤول». ما الحركة الأقوى عند اجتماع الكسرة والضمة؟\n\nمفتاح الإجابة والتغذية الراجعة\nمسؤول ورؤوس؛ همزة مضمومة؛ الكسرة أقوى من الضمة عند تحديد كرسي الهمزة.\n\nتطبيق من الحياة\nعند كتابة شكوى أو طلب رسمي، راجع رسم كلمة «المسؤول» قبل إرسالها.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحدد حركة الهمزة في كلمات مختارة.","يفسر رسم الهمزة المضمومة على واو في أمثلة مناسبة.","يكتب كلمتي «مَسْؤُول» و«رُؤُوس» دون تغيير معانيهما."],"vocabulary":[{"word":"مضمومة","meaning":"حركتها الضمة"},{"word":"واو الهمزة","meaning":"الواو التي تحمل الهمزة المتوسطة عند مناسبة الحركات"}],"quiz":{"prompt":"كيف تُكتب الهمزة في «مَسْؤُول»؟","options":["على واو","على ألف","على ياء","على السطر"],"correct":"على واو"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":23,"title":"القراءة: الكهرباء في وطني","content":"القراءة: الكهرباء في وطني\n\nأهداف التعلّم\n• يستخلص تعليمتي أمان من نص عن الكهرباء.\n• يفرق بين ترشيد الاستهلاك وإجراء الصيانة.\n• يقرأ تنبيهًا عمليًا مكتوبًا قراءة دقيقة.\n\nأتعلّم\nنص تدريبي أصلي من ضاديوم وليس نص الدرس المدرسي: «لاحظت أمينة أن الإنارة بقيت مضاءة في قاعة فارغة، فأطفأت المصابيح التي لا حاجة إليها. رأت بعدها سلكًا مكشوفًا قرب الباب، فلم تلمسه، بل ابتعدت عنه وأخبرت المسؤول عن المبنى. علّق المسؤول لوحة تحذير واستدعى فنيًا مختصًا». الترشيد يقلل الاستهلاك، والسلامة تتطلب عدم الاقتراب من الأسلاك التالفة وترك صيانتها للمختص.\n\nأمثلة توضيحية\nالسلوك الأول ترشيد للطاقة: إطفاء الإنارة غير اللازمة. الثاني سلامة: الابتعاد عن السلك المكشوف وإبلاغ المسؤول المختص.\n\nأنشطة تدريبية\nماذا فعلت أمينة بالمصابيح؟ هل حاولت إصلاح السلك بنفسها؟ اكتب تنبيهًا من سبع كلمات عن عدم لمس الأسلاك المكشوفة.\n\nمفتاح الإجابة والتغذية الراجعة\nأطفأت المصابيح غير اللازمة؛ لا، أبلغت المسؤول؛ مثال «ابتعد عن الأسلاك المكشوفة وأبلغ فنيًا مختصًا فورًا».\n\nتطبيق من الحياة\nراجع مع المسؤول إنارة غرفة خالية، وأبلغ عن أي عطل كهربائي دون لمس الأسلاك أو الأجهزة المعطلة.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يستخلص تعليمتي أمان من نص عن الكهرباء.","يفرق بين ترشيد الاستهلاك وإجراء الصيانة.","يقرأ تنبيهًا عمليًا مكتوبًا قراءة دقيقة."],"vocabulary":[{"word":"ترشيد","meaning":"تقليل الاستهلاك غير الضروري"},{"word":"سلك مكشوف","meaning":"سلك فقد غلافه العازل وقد يشكل خطرًا"}],"quiz":{"prompt":"ما التصرف الصحيح إذا ظهر سلك كهربائي مكشوف؟","options":["الابتعاد وإبلاغ المختص","إصلاحه باليد","سكب الماء عليه","تجاهل وجوده"],"correct":"الابتعاد وإبلاغ المختص"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":24,"title":"القواعد النحوية: الحروف الناسخة","content":"القواعد النحوية: الحروف الناسخة\n\nأهداف التعلّم\n• يسمي حرفين من إن وأخواتها.\n• يبين نصب اسم إن ورفع خبرها.\n• يكون جملة مناسبة تبدأ بـ«لعل».\n\nأتعلّم\nتدخل «إنَّ وأخواتها» على الجملة الاسمية فتنصب المبتدأ اسمًا لها، وترفع الخبر خبرًا لها. في «الوقتُ ثمينٌ» نقول «إنَّ الوقتَ ثمينٌ». «لعلَّ الغائبَ حاضرٌ غدًا» تعبر عن الرجاء حسب السياق. نلاحظ أن اسم إن منصوب والخبر مرفوع، بعكس «كان» التي ترفع الاسم وتنصب الخبر. وقد تختلف علامات الإعراب باختلاف نوع الاسم.\n\nأمثلة توضيحية\n«الخبرُ صحيحٌ» تتحول إلى «إنَّ الخبرَ صحيحٌ». «الدرسُ سهلٌ» تتحول إلى «ليتَ الدرسَ سهلٌ» للتمني في سياق مناسب.\n\nأنشطة تدريبية\nاضبط «إنَّ الموعد ... قريب». صحح «إنَّ الطالبُ مجتهدًا». اكتب جملة رجاء تبدأ بـ«لعل».\n\nمفتاح الإجابة والتغذية الراجعة\n«إنَّ الموعدَ قريبٌ»؛ «إنَّ الطالبَ مجتهدٌ»؛ مثال «لعلَّ النجاحَ قريبٌ».\n\nتطبيق من الحياة\nاكتب جملة تعبر عن أملك في إتقان مهارة جديدة مستخدمًا «لعلَّ»، ثم حدد اسم الحرف وخبره.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يسمي حرفين من إن وأخواتها.","يبين نصب اسم إن ورفع خبرها.","يكون جملة مناسبة تبدأ بـ«لعل»."],"vocabulary":[{"word":"اسم إن","meaning":"اسم منصوب بعد الحرف الناسخ"},{"word":"خبر إن","meaning":"خبر مرفوع يتم به المعنى"}],"quiz":{"prompt":"أي جملة صحيحة؟","options":["إنَّ العملَ مفيدٌ","إنَّ العملُ مفيدًا","إنَّ العملُ مفيدٌ","إنَّ العملَ مفيدًا"],"correct":"إنَّ العملَ مفيدٌ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":25,"title":"الإنتاج الكتابي: المذكرات اليومية (1) و(2)","content":"الإنتاج الكتابي: المذكرات اليومية (1) و(2)\n\nأهداف التعلّم\n• يحدد تاريخًا وموقفًا واحدًا في مذكرة يومية.\n• يفصل بين الحدث والشعور الشخصي.\n• يكتب فقرة متسلسلة عن تجربة تعلم حقيقية.\n\nأتعلّم\nالمذكرة اليومية تكتب عن حدث عاشه الشخص، وقد تتضمن رأيه وشعوره، بخلاف التقرير الرسمي الذي يركز على الوقائع. نص نموذجي أصلي: «الخميس: حضرت اليوم درس قراءة الإعلانات. شعرت بالتردد عندما قرأت أمام زملائي، لكنني تحسنت بعد المحاولة الثانية. سأتمرن عشر دقائق غدًا». نلاحظ الوقت، والحدث، والشعور، والخطة الشخصية. ليست المذكرات مساحة لنقل تفاصيل خاصة عن الآخرين دون إذن.\n\nأمثلة توضيحية\nفي «وصلت مبكرًا» حدث. في «شعرت بالفخر» شعور. في «سأراجع الكلمات غدًا» قرار للمستقبل.\n\nأنشطة تدريبية\nاقرأ النموذج وحدد اليوم والحدث والشعور. اكتب أربع جمل عن أول مرة تعلمت فيها مهارة، وحدد فعلين ماضيين وخطة للمستقبل.\n\nمفتاح الإجابة والتغذية الراجعة\nاليوم الخميس؛ الحدث حضور درس القراءة؛ الشعور التردد ثم التحسن؛ تقبل إجابة شخصية واقعية لا تكشف بيانات الغير.\n\nتطبيق من الحياة\nاكتب مذكرة قصيرة عن إنجاز صغير في التعلم وسجّل خطوة واحدة للممارسة في اليوم التالي.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحدد تاريخًا وموقفًا واحدًا في مذكرة يومية.","يفصل بين الحدث والشعور الشخصي.","يكتب فقرة متسلسلة عن تجربة تعلم حقيقية."],"vocabulary":[{"word":"مذكرات","meaning":"تدوين أحداث وتجارب شخصية"},{"word":"شعور","meaning":"استجابة نفسية للموقف"}],"quiz":{"prompt":"أي عبارة تعبّر عن شعور لا عن حدث؟","options":["شعرتُ بالاطمئنان","دخلتُ الصف","كتبتُ الرسالة","حضرتُ اللقاء"],"correct":"شعرتُ بالاطمئنان"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false}]$DATA$::jsonb)),
target AS (
 SELECT l.id,p.j FROM payload p
 JOIN public.lessons l ON l.title=p.j->>'title'
 JOIN public.units u ON u.id=l.unit_id AND u.semester=1
 JOIN public.grades g ON g.id=u.grade_id AND g.name_ar='الأول متابعة' AND g.grade_number IS NULL
 JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
 JOIN public.countries co ON co.id=cu.country_id AND co.code='BH'
 WHERE l.content='محتوى مقرر في الخطة الرسمية الحالية. يُحفظ العنوان كما في المصدر بعد تنظيف أخطاء OCR الشكلية فقط.'
 AND l.learning_objectives='[]'::jsonb AND l.instructions='[]'::jsonb
)
UPDATE public.lessons l
 SET content=t.j->>'content',learning_objectives=t.j->'learning_objectives',vocabulary=t.j->'vocabulary',
 instructions=jsonb_build_array(jsonb_build_object('origin','DADYOOM_BH_FOLLOWUP1_DRAFT_V1','editorial_review','required','book_text_copied',false)),updated_at=now()
 FROM target t WHERE l.id=t.id;

WITH payload AS (SELECT value AS j FROM jsonb_array_elements($DATA$[{"order":13,"title":"القواعد النحوية: إعراب فعل الأمر","content":"القواعد النحوية: إعراب فعل الأمر\n\nأهداف التعلّم\n• يميز فعل الأمر من الماضي والمضارع في ست جمل.\n• يحدد علامة بناء فعل أمر صحيح الآخر.\n• يوظف فعل الأمر في إرشاد مهذب.\n\nأتعلّم\nفعل الأمر يطلب حصول عمل بعد زمن التكلم. في «اكتبْ اسمك» كلمة «اكتبْ» فعل أمر مبني على السكون؛ لأنه صحيح الآخر ولم يتصل به شيء. وفي «اسعَ إلى الخير» فعل الأمر مبني على حذف حرف العلة. وقد يبنى فعل الأمر على حذف النون كما في «اكتبوا». نحول التعليمات المباشرة إلى صيغة مهذبة بقول «من فضلك، اكتبْ رقم القاعة».\n\nأمثلة توضيحية\nاقرأْ التعليمات، رتّبْ الأوراق، انتظرْ دورك. هذه أوامر صحيحة الآخر مبنية على السكون، وهي ليست أفعالًا مضارعة.\n\nأنشطة تدريبية\nحدّد فعل الأمر في «راجعْ الورقة قبل أن تسلمها». اضبط آخر «اجلس» عندما تخاطب شخصًا واحدًا. اكتب توجيهين مهذبين لزائر جديد.\n\nمفتاح الإجابة والتغذية الراجعة\nراجعْ؛ اجلسْ؛ مثل «افتحْ الباب بلطف» و«احفظْ الأوراق في الملف».\n\nتطبيق من الحياة\nعند إرشاد دارس إلى غرفة التسجيل، استخدم أمرًا واحدًا صحيحًا ومهذبًا لا يتضمن إساءة.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز فعل الأمر من الماضي والمضارع في ست جمل.","يحدد علامة بناء فعل أمر صحيح الآخر.","يوظف فعل الأمر في إرشاد مهذب."],"vocabulary":[{"word":"الأمر","meaning":"طلب أداء عمل"},{"word":"البناء","meaning":"ثبات نهاية الفعل وفق صورته"}],"quiz":{"prompt":"ما علامة بناء فعل الأمر «اكتبْ»؟","options":["السكون","الضمة","الفتحة الظاهرة دائمًا","الكسرة"],"correct":"السكون"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":14,"title":"الإنتاج الكتابي: الرسالة الشخصية (1)","content":"الإنتاج الكتابي: الرسالة الشخصية (1)\n\nأهداف التعلّم\n• يميز بين المرسل والمرسل إليه.\n• يكتب تحية مناسبة لرسالة شخصية.\n• يرتب المقدمة والمتن والخاتمة.\n\nأتعلّم\nالرسالة الشخصية وسيلة للتواصل مع قريب أو صديق. نبدأ باسم المخاطب وتحية واضحة، ثم نتناول سبب الكتابة في متن قصير، ونختم بدعاء أو عبارة تقدير واسم المرسل. مثال من ضاديوم: «صديقي علي، السلام عليكم. أكتب لأطمئن على صحتك بعد غيابك عن الدرس. نرجو أن نراك قريبًا. صديقك سالم». ينبغي ألا نضع بيانات شخصية خاصة لا حاجة لها.\n\nأمثلة توضيحية\nرسالة شخصية: «أختي العزيزة، أشكرك على مساعدتك في تعلم استخدام الهاتف. أخوك أحمد». يظهر اسم المخاطب، والغرض، والتوقيع.\n\nأنشطة تدريبية\nحدد المرسل والمرسل إليه في المثال الأول. رتب: توقيع / تحية / الغرض. اكتب رسالة من أربع جمل تطمئن فيها على صديق.\n\nمفتاح الإجابة والتغذية الراجعة\nالمرسل سالم، والمرسل إليه علي؛ الترتيب تحية ثم الغرض ثم التوقيع. تقبل رسالة مهذبة لها سبب واضح.\n\nتطبيق من الحياة\nاكتب رسالة شكر لأحد أفراد الأسرة مستخدمًا عبارات تحترم خصوصيته وتذكر المساعدة دون تفاصيل محرجة.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز بين المرسل والمرسل إليه.","يكتب تحية مناسبة لرسالة شخصية.","يرتب المقدمة والمتن والخاتمة."],"vocabulary":[{"word":"المرسل","meaning":"كاتب الرسالة"},{"word":"المتن","meaning":"الفقرات التي تحمل الغرض"}],"quiz":{"prompt":"ما الجزء الذي يوضح سبب إرسال الرسالة؟","options":["المتن","التوقيع وحده","عنوان الملف","رقم الصفحة"],"correct":"المتن"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":15,"title":"القواعد النحوية: الفاعل","content":"القواعد النحوية: الفاعل\n\nأهداف التعلّم\n• يحدد الفاعل في جملة فعلية مثبتة.\n• يميز علامة رفع الفاعل المفرد.\n• يبدل اسم الفاعل دون تغيير الحدث.\n\nأتعلّم\nالفاعل اسم مرفوع يدل على من قام بالفعل، أو اتصف به بحسب معنى الجملة. في «فتحَ الموظفُ النافذةَ» الفاعل «الموظفُ» مرفوع بالضمة، و«النافذةَ» مفعول به. وقد يأتي الفاعل بعد الفعل أو يتصل به ضميرًا مثل «كتبتُ». لا نحكم على الكلمة من موضعها وحده؛ نسأل: من قام بالفعل؟ ونتحقق من إعرابها.\n\nأمثلة توضيحية\nوصلَ البريدُ صباحًا؛ الفاعل البريدُ. ساعدَتْ فاطمةُ جارتَها؛ الفاعل فاطمةُ.\n\nأنشطة تدريبية\nحدّد الفاعل في «قرأَ سالمٌ التنبيهَ». استبدل «سالمٌ» بـ«الموظفُ». ضع الحركة الصحيحة على كلمة «الطبيب» في «حضرَ الطبيبُ».\n\nمفتاح الإجابة والتغذية الراجعة\nالفاعل «سالمٌ»؛ «قرأ الموظفُ التنبيهَ»؛ «الطبيبُ» مرفوع بالضمة.\n\nتطبيق من الحياة\nاكتب جملة تصف من استلم وثيقة في العمل وحدد الاسم الذي أدى الفعل.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحدد الفاعل في جملة فعلية مثبتة.","يميز علامة رفع الفاعل المفرد.","يبدل اسم الفاعل دون تغيير الحدث."],"vocabulary":[{"word":"الفاعل","meaning":"اسم يدل على من قام بالفعل"},{"word":"الرفع","meaning":"حالة إعرابية من علاماتها الضمة"}],"quiz":{"prompt":"من الفاعل في «أرسلَ الأبُ رسالةً»؟","options":["الأبُ","رسالةً","أرسلَ","لا يوجد"],"correct":"الأبُ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":16,"title":"الإملاء: الهمزة المتوسطة المفتوحة وما قبلها حرف ساكن غير المد","content":"الإملاء: الهمزة المتوسطة المفتوحة وما قبلها حرف ساكن غير المد\n\nأهداف التعلّم\n• يشرح أثر سكون الحرف السابق للهمزة المفتوحة.\n• يكتب «مسألة» و«فجأة» كتابة سليمة.\n• يميز هذه الحالة من همزة قبلها حرف مد.\n\nأتعلّم\nعند رسم الهمزة المتوسطة ننظر إلى حركتها وحركة الحرف السابق. إذا كانت الهمزة مفتوحة وقبلها حرف صحيح ساكن، مثل «مَسْأَلَة» و«فَجْأَة»، كتبت على ألف؛ لأن الفتحة أقوى من السكون، ومناسب الفتحة الألف. أما إذا سبق الهمزة حرف مد فقد تختلف القاعدة وتحتاج فحصًا خاصًا؛ لذلك لا نعمم هذا المثال على كل كلمة فيها سكون.\n\nأمثلة توضيحية\n«مسألة» فيها السين ساكنة والهمزة مفتوحة. «فجأة» فيها الجيم ساكنة والهمزة مفتوحة. نقرأ الكلمة ثم نكتبها مع تحديد كرسي الهمزة.\n\nأنشطة تدريبية\nأكمل رسم «مسـ_لة» و«فجـ_ة». ما حركة الحرف قبل الهمزة في الكلمتين؟ اكتب جملة قصيرة تحوي كلمة «مسألة».\n\nمفتاح الإجابة والتغذية الراجعة\nمسألة، فجأة؛ الحرف السابق ساكن؛ مثال «حللتُ مسألةً في الوقت المحدد».\n\nتطبيق من الحياة\nعند إرسال سؤال مكتوب إلى المعلم، راجع رسم كلمة «مسألة» قبل الإرسال.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يشرح أثر سكون الحرف السابق للهمزة المفتوحة.","يكتب «مسألة» و«فجأة» كتابة سليمة.","يميز هذه الحالة من همزة قبلها حرف مد."],"vocabulary":[{"word":"حرف صحيح ساكن","meaning":"حرف ليس مدًا وخالٍ من الحركة"},{"word":"كرسي الهمزة","meaning":"شكل الحرف الذي تحمل عليه"}],"quiz":{"prompt":"لماذا كتبت الهمزة على ألف في «فَجْأَة»؟","options":["لأنها مفتوحة وما قبلها ساكن صحيح","لأنها مكسورة","لأنها في أول الكلمة","لأن ما قبلها ألف مد"],"correct":"لأنها مفتوحة وما قبلها ساكن صحيح"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":17,"title":"الإنتاج الكتابي: الرسالة الشخصية (2)","content":"الإنتاج الكتابي: الرسالة الشخصية (2)\n\nأهداف التعلّم\n• يراجع لغة الرسالة وخلوها من العبارات الجارحة.\n• ينظم أحداثًا شخصية بتسلسل مفهوم.\n• يعيد تحرير رسالة بعد ملاحظة زميل.\n\nأتعلّم\nفي المرحلة الثانية نطور الرسالة الشخصية من مسودة قصيرة إلى رسالة مترابطة. نراجع: هل حددت سبب الكتابة؟ هل العبارات مناسبة للمخاطب؟ هل تتصل جملة بأخرى؟ في رسالة دعوة لصديق، من الأفضل كتابة المكان والموعد بوضوح، ثم طلب رد مختصر. عند الكتابة بالهاتف ننتبه إلى عدم إرسال العنوان الكامل في مجموعة عامة؛ فقد تكفي وسيلة تواصل خاصة.\n\nأمثلة توضيحية\nمسودة غير واضحة: «تعال في وقت ما». بعد المراجعة: «يسعدني حضورك مساء الخميس؛ سأرسل لك تفاصيل الموعد في رسالة خاصة».\n\nأنشطة تدريبية\nحسّن «لماذا تأخرت؟ أنت مهمل» إلى سؤال مهذب. أضف خاتمة لرسالة زيارة مريض. راجع الرسالة التي كتبتها سابقًا من جهة الترتيب والتهجئة.\n\nمفتاح الإجابة والتغذية الراجعة\nمثال «اطمئن عليك وأرجو أن تكون بخير، هل تحتاج أي مساعدة؟»؛ خاتمة «مع أطيب الدعوات بالشفاء، صديقك...»\n\nتطبيق من الحياة\nقبل إرسال رسالة إلى قريب، راجع اسم المخاطب والسبب والتاريخ وتأكد من خصوصية البيانات.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يراجع لغة الرسالة وخلوها من العبارات الجارحة.","ينظم أحداثًا شخصية بتسلسل مفهوم.","يعيد تحرير رسالة بعد ملاحظة زميل."],"vocabulary":[{"word":"مراجعة","meaning":"فحص النص لتحسينه"},{"word":"ترابط","meaning":"اتصال الأفكار في تسلسل مفهوم"}],"quiz":{"prompt":"ما التحسين الأهم عند مراجعة رسالة شخصية؟","options":["وضوح الغرض وملاءمة اللغة","حذف التحية دائمًا","إضافة تفاصيل غير مؤكدة","كتابة فقرة بلا علامات"],"correct":"وضوح الغرض وملاءمة اللغة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":18,"title":"القراءة: البحرين تتكلم - دراسة القصيدة كاملة وحفظ القصيدة كاملة","content":"القراءة: البحرين تتكلم - دراسة القصيدة كاملة وحفظ القصيدة كاملة\n\nأهداف التعلّم\n• يميز موضوع الانتماء في نص تدريبي أصلي.\n• يشرح صورة تعبيرية بسيطة عن الوطن.\n• يتدرب على الإلقاء مع الفصل بين النص الأصلي والقصيدة الرسمية.\n\nأتعلّم\nالعنوان المسجل في الخطة هو «البحرين تتكلم» وتتضمن المهمة الرسمية دراسة القصيدة كاملة وحفظها، لكن نص القصيدة وفهرس الكتاب لم تتم مطابقتهما هنا. لذلك نقدم تدريبًا أصليًا مختلفًا، وليس بديلًا عن حفظ القصيدة: «صوت البحر في صباح المدينة يذكرنا بالعمل والصبر. يلتقي الناس في المدارس والأسواق، ولكل إنسان دور في خدمة المكان الذي يحبه». نميز المعنى المباشر من التعبير المجازي، ثم نقرأ بأسلوب واضح.\n\nأمثلة توضيحية\nالتعبير «صوت البحر يذكرنا بالصبر» فيه تصوير للبحر وكأنه يبعث رسالة، ولا يعني أن البحر يتحدث حقيقة. الفكرة هي ارتباط الإنسان بوطنه وعمله.\n\nأنشطة تدريبية\nما المكانان المذكوران في النص الأصلي؟ فسّر عبارة «صوت البحر يذكرنا بالصبر». اكتب ثلاث جمل عن سلوك يحافظ على مكان عام. احفظ فقط النص الرسمي بعد التحقق من مصدره.\n\nمفتاح الإجابة والتغذية الراجعة\nالمدارس والأسواق؛ العبارة صورة تربط البحر بالصبر والعمل؛ تقبل جمل عملية مثل المحافظة على النظافة واحترام المرافق. الحفظ الرسمي غير مُتحقق منه في هذه المسودة.\n\nتطبيق من الحياة\nسجّل بصوتك فقرة أصلية قصيرة عن خدمة المجتمع، مع مراعاة الوقف الواضح وعدم الادعاء أنها القصيدة المقررة.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز موضوع الانتماء في نص تدريبي أصلي.","يشرح صورة تعبيرية بسيطة عن الوطن.","يتدرب على الإلقاء مع الفصل بين النص الأصلي والقصيدة الرسمية."],"vocabulary":[{"word":"انتماء","meaning":"صلة الإنسان بمكانه ومجتمعه"},{"word":"صورة تعبيرية","meaning":"أسلوب يرسم معنى في الخيال"}],"quiz":{"prompt":"ما وضع النص التدريبي هنا مقارنة بقصيدة «البحرين تتكلم»؟","options":["نص أصلي داعم لا يحل محل القصيدة الرسمية","النص الرسمي الكامل","دليل حفظ القصيدة المقررة","صورة من الكتاب"],"correct":"نص أصلي داعم لا يحل محل القصيدة الرسمية"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":19,"title":"القواعد النحوية: المفعول به","content":"القواعد النحوية: المفعول به\n\nأهداف التعلّم\n• يحدد المفعول به في ثلاث جمل فعلية.\n• يميز الفاعل عن المفعول به.\n• يضبط المفعول به المفرد بالفتحة في مثال واضح.\n\nأتعلّم\nالمفعول به اسم منصوب وقع عليه فعل الفاعل في الجملة المتعدية. «قرأَ الدارسُ الإعلانَ»: الدارس فاعل مرفوع؛ الإعلان مفعول به منصوب بالفتحة. نسأل ماذا قرأ الدارس؟ فنحصل على المفعول به. ليست كل الأفعال بحاجة إلى مفعول؛ فـ«جلسَ الدارسُ» جملة تامة. وقد تكون علامة النصب مختلفة في المثنى والجمع، لكن البداية بالمفرد.\n\nأمثلة توضيحية\nأعدَّ الموظفُ التقريرَ. شرحَ المدربُ التعليماتِ؛ «التقريرَ» منصوب بالفتحة و«التعليماتِ» جمع مؤنث سالم منصوب بالكسرة.\n\nأنشطة تدريبية\nحدد المفعول في «نظّمَ سالمٌ الملفاتِ». استبدل الملفات بكلمة «الموعد» واضبطها. لماذا لا يوجد مفعول به في «خرج الموظفُ»؟\n\nمفتاح الإجابة والتغذية الراجعة\nالملفاتِ؛ «نظم سالمٌ الموعدَ»؛ لأن فعل «خرج» لازم هنا واكتفى بالفاعل.\n\nتطبيق من الحياة\nصف إجراء في مكتب باستخدام جملة فيها فاعل ومفعول به، مثل تسجيل موعد أو قراءة رسالة.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحدد المفعول به في ثلاث جمل فعلية.","يميز الفاعل عن المفعول به.","يضبط المفعول به المفرد بالفتحة في مثال واضح."],"vocabulary":[{"word":"المفعول به","meaning":"اسم وقع عليه فعل الفاعل"},{"word":"الفعل المتعدي","meaning":"فعل يتجاوز فاعله إلى مفعول"}],"quiz":{"prompt":"ما المفعول به في «قرأَ سالمٌ الرسالةَ»؟","options":["الرسالةَ","سالمٌ","قرأَ","لا يوجد"],"correct":"الرسالةَ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":20,"title":"القواعد النحوية: المبتدأ والخبر","content":"القواعد النحوية: المبتدأ والخبر\n\nأهداف التعلّم\n• يميّز ركني الجملة الاسمية.\n• يرفع مبتدأ وخبرًا مفردين بالضمة.\n• يحول وصفًا قصيرًا إلى جملة اسمية تامة.\n\nأتعلّم\nالجملة الاسمية تبدأ غالبًا بمبتدأ نتحدث عنه، ثم خبر يكمل الفائدة. «الدرسُ مفيدٌ»: الدرسُ مبتدأ مرفوع بالضمة، ومفيدٌ خبر مرفوع بالضمة. إذا قلنا «الدرسُ» فقط لم تتم الفائدة. قد يأتي الخبر شبه جملة، مثل «الكتابُ على الطاولة»؛ فلا نعامله كخبر مفرد مرفوع بالضمة. نحاول أولًا التمييز بين المثالين.\n\nأمثلة توضيحية\n«المكتبةُ مفتوحةٌ» مبتدأ وخبر مفرد. «الطلابُ في القاعةِ» مبتدأ وخبر شبه جملة.\n\nأنشطة تدريبية\nعيّن الخبر في «الشارعُ نظيفٌ». أكمل «الورقةُ ...» بخبر مناسب. ضع الحركتين في «القلم جديد».\n\nمفتاح الإجابة والتغذية الراجعة\nالخبر «نظيفٌ»؛ مثل «الورقةُ واضحةٌ»؛ «القلمُ جديدٌ».\n\nتطبيق من الحياة\nاكتب جملتين اسميتين تصف بهما مكان التعلم أو خدمات مكتبة الحي.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميّز ركني الجملة الاسمية.","يرفع مبتدأ وخبرًا مفردين بالضمة.","يحول وصفًا قصيرًا إلى جملة اسمية تامة."],"vocabulary":[{"word":"مبتدأ","meaning":"اسم تبدأ به الجملة الاسمية غالبًا"},{"word":"خبر","meaning":"جزء يتم به معنى المبتدأ"}],"quiz":{"prompt":"ما الخبر في «الموعدُ قريبٌ»؟","options":["قريبٌ","الموعدُ","الموعد","لا يوجد خبر"],"correct":"قريبٌ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":21,"title":"القواعد النحوية: الأفعال الناسخة","content":"القواعد النحوية: الأفعال الناسخة\n\nأهداف التعلّم\n• يوضح أثر «كان» في جملة اسمية بسيطة.\n• يميز اسم كان وخبرها.\n• يكون جملة صحيحة باستخدام «أصبح».\n\nأتعلّم\nتدخل «كان وأخواتها» على الجملة الاسمية، فترفع المبتدأ اسمًا لها وتنصب الخبر خبرًا لها. نقول «الجوُّ معتدلٌ» ثم «كان الجوُّ معتدلًا». بقي «الجوُّ» مرفوعًا وصار «معتدلًا» منصوبًا. «أصبح الطريقُ مزدحمًا» مثال آخر، ويشير «أصبح» إلى حدوث الحالة صباحًا أو الصيرورة بحسب السياق. لا نضع الفتحة على الاسم، بل على الخبر المفرد.\n\nأمثلة توضيحية\n«الدرسُ سهلٌ» تصبح «صار الدرسُ سهلًا». «المركزُ مفتوحٌ» تصبح «أصبح المركزُ مفتوحًا».\n\nأنشطة تدريبية\nحوّل «الطقسُ جميلٌ» إلى جملة تبدأ بـ«كان». حدّد اسم كان وخبرها. صحح «كان الجوَّ لطيفٌ».\n\nمفتاح الإجابة والتغذية الراجعة\n«كان الطقسُ جميلًا»؛ اسمها الطقسُ وخبرها جميلًا؛ «كان الجوُّ لطيفًا».\n\nتطبيق من الحياة\nدوّن تغيرًا حدث في يومك بعبارة تبدأ بـ«أصبح»، ثم راجع ضبط الخبر.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يوضح أثر «كان» في جملة اسمية بسيطة.","يميز اسم كان وخبرها.","يكون جملة صحيحة باستخدام «أصبح»."],"vocabulary":[{"word":"ناسخ","meaning":"فعل يغير حكم المبتدأ والخبر"},{"word":"خبر كان","meaning":"جزء منصوب يكمل معنى كان"}],"quiz":{"prompt":"ما الضبط الصحيح بعد «كان»؟","options":["كان المكانُ نظيفًا","كان المكانَ نظيفٌ","كان المكانَ نظيفًا","كان المكانُ نظيفٌ"],"correct":"كان المكانُ نظيفًا"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":22,"title":"الإملاء: الهمزة المتوسطة المضمومة","content":"الإملاء: الهمزة المتوسطة المضمومة\n\nأهداف التعلّم\n• يحدد حركة الهمزة في كلمات مختارة.\n• يفسر رسم الهمزة المضمومة على واو في أمثلة مناسبة.\n• يكتب كلمتي «مَسْؤُول» و«رُؤُوس» دون تغيير معانيهما.\n\nأتعلّم\nإذا كانت الهمزة المتوسطة مضمومة، ننظر إلى حركتها وحركة ما قبلها؛ الضمة تناسب الواو ما لم توجد كسرة أقوى. مثال «مَسْؤُول»: الهمزة مضمومة وما قبلها ساكن صحيح، فتكتب على واو. ومثال «رُؤُوس» تظهر الهمزة على واو، مع الانتباه إلى الرسم المعجمي. أما «فِئَة» فكسرة ما قبل الهمزة أقوى، فترسم على ياء رغم فتحها. القاعدة لا تعتمد على ضمة الهمزة وحدها بمعزل عن الحرف السابق.\n\nأمثلة توضيحية\n«المسؤولُ يقرأُ الرسالةَ». «يتفاءلُ الناسُ بالمستقبل» فيها همزة متوسطة على ألف؛ لأننا لا نساوي بين كل الهمزات.\n\nأنشطة تدريبية\nأكمل «مسـ_ول» و«ر_وس». اذكر حركة الهمزة في «مسؤول». ما الحركة الأقوى عند اجتماع الكسرة والضمة؟\n\nمفتاح الإجابة والتغذية الراجعة\nمسؤول ورؤوس؛ همزة مضمومة؛ الكسرة أقوى من الضمة عند تحديد كرسي الهمزة.\n\nتطبيق من الحياة\nعند كتابة شكوى أو طلب رسمي، راجع رسم كلمة «المسؤول» قبل إرسالها.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحدد حركة الهمزة في كلمات مختارة.","يفسر رسم الهمزة المضمومة على واو في أمثلة مناسبة.","يكتب كلمتي «مَسْؤُول» و«رُؤُوس» دون تغيير معانيهما."],"vocabulary":[{"word":"مضمومة","meaning":"حركتها الضمة"},{"word":"واو الهمزة","meaning":"الواو التي تحمل الهمزة المتوسطة عند مناسبة الحركات"}],"quiz":{"prompt":"كيف تُكتب الهمزة في «مَسْؤُول»؟","options":["على واو","على ألف","على ياء","على السطر"],"correct":"على واو"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":23,"title":"القراءة: الكهرباء في وطني","content":"القراءة: الكهرباء في وطني\n\nأهداف التعلّم\n• يستخلص تعليمتي أمان من نص عن الكهرباء.\n• يفرق بين ترشيد الاستهلاك وإجراء الصيانة.\n• يقرأ تنبيهًا عمليًا مكتوبًا قراءة دقيقة.\n\nأتعلّم\nنص تدريبي أصلي من ضاديوم وليس نص الدرس المدرسي: «لاحظت أمينة أن الإنارة بقيت مضاءة في قاعة فارغة، فأطفأت المصابيح التي لا حاجة إليها. رأت بعدها سلكًا مكشوفًا قرب الباب، فلم تلمسه، بل ابتعدت عنه وأخبرت المسؤول عن المبنى. علّق المسؤول لوحة تحذير واستدعى فنيًا مختصًا». الترشيد يقلل الاستهلاك، والسلامة تتطلب عدم الاقتراب من الأسلاك التالفة وترك صيانتها للمختص.\n\nأمثلة توضيحية\nالسلوك الأول ترشيد للطاقة: إطفاء الإنارة غير اللازمة. الثاني سلامة: الابتعاد عن السلك المكشوف وإبلاغ المسؤول المختص.\n\nأنشطة تدريبية\nماذا فعلت أمينة بالمصابيح؟ هل حاولت إصلاح السلك بنفسها؟ اكتب تنبيهًا من سبع كلمات عن عدم لمس الأسلاك المكشوفة.\n\nمفتاح الإجابة والتغذية الراجعة\nأطفأت المصابيح غير اللازمة؛ لا، أبلغت المسؤول؛ مثال «ابتعد عن الأسلاك المكشوفة وأبلغ فنيًا مختصًا فورًا».\n\nتطبيق من الحياة\nراجع مع المسؤول إنارة غرفة خالية، وأبلغ عن أي عطل كهربائي دون لمس الأسلاك أو الأجهزة المعطلة.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يستخلص تعليمتي أمان من نص عن الكهرباء.","يفرق بين ترشيد الاستهلاك وإجراء الصيانة.","يقرأ تنبيهًا عمليًا مكتوبًا قراءة دقيقة."],"vocabulary":[{"word":"ترشيد","meaning":"تقليل الاستهلاك غير الضروري"},{"word":"سلك مكشوف","meaning":"سلك فقد غلافه العازل وقد يشكل خطرًا"}],"quiz":{"prompt":"ما التصرف الصحيح إذا ظهر سلك كهربائي مكشوف؟","options":["الابتعاد وإبلاغ المختص","إصلاحه باليد","سكب الماء عليه","تجاهل وجوده"],"correct":"الابتعاد وإبلاغ المختص"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":24,"title":"القواعد النحوية: الحروف الناسخة","content":"القواعد النحوية: الحروف الناسخة\n\nأهداف التعلّم\n• يسمي حرفين من إن وأخواتها.\n• يبين نصب اسم إن ورفع خبرها.\n• يكون جملة مناسبة تبدأ بـ«لعل».\n\nأتعلّم\nتدخل «إنَّ وأخواتها» على الجملة الاسمية فتنصب المبتدأ اسمًا لها، وترفع الخبر خبرًا لها. في «الوقتُ ثمينٌ» نقول «إنَّ الوقتَ ثمينٌ». «لعلَّ الغائبَ حاضرٌ غدًا» تعبر عن الرجاء حسب السياق. نلاحظ أن اسم إن منصوب والخبر مرفوع، بعكس «كان» التي ترفع الاسم وتنصب الخبر. وقد تختلف علامات الإعراب باختلاف نوع الاسم.\n\nأمثلة توضيحية\n«الخبرُ صحيحٌ» تتحول إلى «إنَّ الخبرَ صحيحٌ». «الدرسُ سهلٌ» تتحول إلى «ليتَ الدرسَ سهلٌ» للتمني في سياق مناسب.\n\nأنشطة تدريبية\nاضبط «إنَّ الموعد ... قريب». صحح «إنَّ الطالبُ مجتهدًا». اكتب جملة رجاء تبدأ بـ«لعل».\n\nمفتاح الإجابة والتغذية الراجعة\n«إنَّ الموعدَ قريبٌ»؛ «إنَّ الطالبَ مجتهدٌ»؛ مثال «لعلَّ النجاحَ قريبٌ».\n\nتطبيق من الحياة\nاكتب جملة تعبر عن أملك في إتقان مهارة جديدة مستخدمًا «لعلَّ»، ثم حدد اسم الحرف وخبره.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يسمي حرفين من إن وأخواتها.","يبين نصب اسم إن ورفع خبرها.","يكون جملة مناسبة تبدأ بـ«لعل»."],"vocabulary":[{"word":"اسم إن","meaning":"اسم منصوب بعد الحرف الناسخ"},{"word":"خبر إن","meaning":"خبر مرفوع يتم به المعنى"}],"quiz":{"prompt":"أي جملة صحيحة؟","options":["إنَّ العملَ مفيدٌ","إنَّ العملُ مفيدًا","إنَّ العملُ مفيدٌ","إنَّ العملَ مفيدًا"],"correct":"إنَّ العملَ مفيدٌ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":25,"title":"الإنتاج الكتابي: المذكرات اليومية (1) و(2)","content":"الإنتاج الكتابي: المذكرات اليومية (1) و(2)\n\nأهداف التعلّم\n• يحدد تاريخًا وموقفًا واحدًا في مذكرة يومية.\n• يفصل بين الحدث والشعور الشخصي.\n• يكتب فقرة متسلسلة عن تجربة تعلم حقيقية.\n\nأتعلّم\nالمذكرة اليومية تكتب عن حدث عاشه الشخص، وقد تتضمن رأيه وشعوره، بخلاف التقرير الرسمي الذي يركز على الوقائع. نص نموذجي أصلي: «الخميس: حضرت اليوم درس قراءة الإعلانات. شعرت بالتردد عندما قرأت أمام زملائي، لكنني تحسنت بعد المحاولة الثانية. سأتمرن عشر دقائق غدًا». نلاحظ الوقت، والحدث، والشعور، والخطة الشخصية. ليست المذكرات مساحة لنقل تفاصيل خاصة عن الآخرين دون إذن.\n\nأمثلة توضيحية\nفي «وصلت مبكرًا» حدث. في «شعرت بالفخر» شعور. في «سأراجع الكلمات غدًا» قرار للمستقبل.\n\nأنشطة تدريبية\nاقرأ النموذج وحدد اليوم والحدث والشعور. اكتب أربع جمل عن أول مرة تعلمت فيها مهارة، وحدد فعلين ماضيين وخطة للمستقبل.\n\nمفتاح الإجابة والتغذية الراجعة\nاليوم الخميس؛ الحدث حضور درس القراءة؛ الشعور التردد ثم التحسن؛ تقبل إجابة شخصية واقعية لا تكشف بيانات الغير.\n\nتطبيق من الحياة\nاكتب مذكرة قصيرة عن إنجاز صغير في التعلم وسجّل خطوة واحدة للممارسة في اليوم التالي.\n\nتنبيه: هذا درس أصلي داعم من تأليف ضاديوم وفق عنوان الخطة الرسمية للتعليم المستمر بمملكة البحرين للعام 2026–2027، وليس نقلًا من الكتاب الرسمي أو شهادة اكتمال فهرسه. المحتوى يحتاج مراجعة تربوية تحريرية، وأي حفظ للنص الشعري الرسمي ينتظر التحقق من الكتاب.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحدد تاريخًا وموقفًا واحدًا في مذكرة يومية.","يفصل بين الحدث والشعور الشخصي.","يكتب فقرة متسلسلة عن تجربة تعلم حقيقية."],"vocabulary":[{"word":"مذكرات","meaning":"تدوين أحداث وتجارب شخصية"},{"word":"شعور","meaning":"استجابة نفسية للموقف"}],"quiz":{"prompt":"أي عبارة تعبّر عن شعور لا عن حدث؟","options":["شعرتُ بالاطمئنان","دخلتُ الصف","كتبتُ الرسالة","حضرتُ اللقاء"],"correct":"شعرتُ بالاطمئنان"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false}]$DATA$::jsonb))
INSERT INTO public.lesson_activities(lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
SELECT l.id,'تحقق من الفهم — سؤال ضاديوم الأصلي','multiple_choice',
 'اختر إجابة مناسبة. السؤال من تأليف ضاديوم ويحتاج إلى مراجعة تربوية.',
 jsonb_build_object('origin','DADYOOM_BH_FOLLOWUP1_MCQ_V1','options',p.j->'quiz'->'options','editorial_review','required','book_text_copied',false),1,5,true,
 'assessment',p.j->'quiz'->>'prompt',jsonb_build_object('correct',p.j->'quiz'->>'correct'),false
FROM payload p
JOIN public.lessons l ON l.title=p.j->>'title' AND l.content LIKE '%SOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1%'
JOIN public.units u ON u.id=l.unit_id AND u.semester=1
JOIN public.grades g ON g.id=u.grade_id AND g.name_ar='الأول متابعة' AND g.grade_number IS NULL
JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
JOIN public.countries co ON co.id=cu.country_id AND co.code='BH'
WHERE NOT EXISTS(SELECT 1 FROM lesson_activities a WHERE a.lesson_id=l.id AND a.content->>'origin'='DADYOOM_BH_FOLLOWUP1_MCQ_V1');